<?php class AuthController {function login(){if(auth())redirect('?page=dashboard');$err=null;if($_SERVER['REQUEST_METHOD']==='POST'){ $s=Database::connect()->prepare('SELECT * FROM users WHERE username=? AND status="aktif"');$s->execute([$_POST['username']]);$u=$s->fetch();if($u&&password_verify($_POST['password'],$u['password'])){$_SESSION['user']=$u;redirect('?page=dashboard');}$err='Username atau password salah.';}require __DIR__.'/../views/auth/login.php';}function logout(){session_destroy();redirect('?page=login');}}
